-- The component registry. Each component is a folder with a manifest.json (the host lists them: LuaHost.ComponentList):
-- the shared ones and the tools under lua/components, an interface's own panels under lua/interfaces/<id>/panels
-- (Modern's: s6-modular-g round 15). Another interface's panels without one come from its interface.lua
-- (core/interfaces.lua, PanelManifests). Each has:
--
--   manifest.json  name, title, version, order, and the files to load ("settings", "main")
--   settings.lua   its defaults and its settings schema (pages generated by the settings window)
--   main.lua       its frames and behaviour
--
-- Both files get the component object with TK.GetComponent(name). A component implements:
--
--   C:OnEnable()        create frames (once, after the profile is loaded)
--   C:ApplySettings()   apply every setting from its profile table; called on start, on each change and on a
--                        profile switch, so it must be idempotent
--   C:SettingsNodes()   optional: its entries in the settings tree (default: one node); a node's parent field puts it
--                        under another entry, to any depth (s6-ui-settings: core/settings.lua's header)
--   C:OnSettingChanged(node, key, value)  optional: a finer-grained reaction than ApplySettings
--
-- Its root frames are its own (C:Own; TK.Visibility:Attach during its OnEnable or ApplySettings marks them too), the
-- ones it makes later included; TK.ReplaceComponent hides them for the session (the mod sandbox's native fallback).
--
-- s6-interface-5x (round 13, the separation's step 11; docs/development/interface-separation.md 5.18; the owner's answer
-- to Q52): only what is turned on is loaded. Every component's settings.lua loads at the start, and an interface panel's
-- main.lua (a component under interfaces/) only while one of its panels is in use (TK.Interfaces:InUse): turned on in
-- the game it is started alone (Start, through the host), turned off it is unloaded (Unload: closed by its own hide path,
-- what it made withdrawn and destroyed, its code dropped). A component that draws several panels may give each its own
-- lifecycle:
--
--   C:PanelOn(id)       create, register and listen for panel id (called while it is in use, after OnEnable)
--   C:PanelOff(id)      its close and hide cleanup, before what PanelOn made is withdrawn and destroyed
--
-- What a panel made is known by its owner (Components:Owner): the component loading, enabling or applying its settings
-- at the time, with the panel PanelOn runs for, or else the file that made it. Its commands stay declared (its
-- manifest's commands), so their keys stay bound, inert while it is off (TK.Bindings:Inert).

local Components = { list = {}, byName = {},
                     loaded = {},      -- name -> true: its main.lua ran
                     unloadable = {},  -- name -> true: an interface panel's component, loaded only while in use
                     started = {},     -- name -> { panel id -> true }: its panels started (PanelOn)
                     owned = {},       -- name -> { frame, ... }: what its code made (Adopt)
                     made = {},        -- name -> { key, ... }: the TK fields its main.lua's files set (LoadMain)
                     readers = {},     -- component -> true: reads its settings through Applied (s6-optimize round 33)
}
TK.Components = Components

local Component = {}
Component.__index = Component

function TK.GetComponent(name)
    return Components.byName[name]
end

function Component:DB()
    return TK.DB:Component(self.name)
end

--- s6-interface-5x (round 13, the separation's step 11): whether its main.lua runs (TK.Components:Loaded). Its page
--- (settings.lua) is there either way, and calls into main.lua only while this is true.
function Component:Loaded()
    return Components:Loaded(self.name)
end

--- Marks a root frame (one made on UIParent) as the component's, so TK.ReplaceComponent hides it; a frame made while
--- the component is replaced is hidden at once. Returns the frame.
function Component:Own(frame)
    if rawget(frame, "__component") then return frame end
    frame.__component = self
    Components:Adopt(frame, self.name, Components.panel) -- s6-interface-5x (round 13): it goes with the component
    self.roots = self.roots or {}
    self.roots[#self.roots + 1] = frame
    if self.replaced then
        frame.__want = __tk:IsShown(frame.__h)
        __tk:SetShown(frame.__h, false)
    end
    return frame
end

--- The default settings tree node: the component's title with its tabs.
function Component:SettingsNodes()
    return {
        {
            id = self.name,
            title = self.title,
            order = self.order,
            tabs = self.tabs or {},
            atLogin = self.atLogin,
            category = self.category, -- s6-ui-settings: the settings list's tab (core/settings.lua), interface by default
            listTop = self.listTop, -- s6-interface-5x (round 12): first in its tab's list, above the interfaces' (TK.Panels:GroupRoots)
            db = function() return self:DB() end,
            defaults = function() return self.defaults end, -- s6-ui-settings: what the page's reset icon puts back
        },
    }
end

--- The allowed values of the component's settings, from its schema: number ranges and select choices, by key.
--- Profiles are checked against these when loaded (review F3).
function Component:ValueRules()
    if self._rules then return self._rules end
    local rules = {}
    local ok, nodes = pcall(self.SettingsNodes, self)
    for _, node in ipairs(ok and nodes or {}) do
        for _, tab in ipairs(node.tabs or {}) do
            for _, arg in ipairs(TK.Settings.Controls(tab)) do -- s6-ui-core (round 57): a row's controls too
                if arg.key and arg.type == "range" and arg.min and arg.max then
                    -- s6-ui-core (round 60): a slider's end stop past them is a value of its own
                    rules[arg.key] = { min = arg.min, max = arg.max, stop = arg.stop and arg.stop.value }
                elseif arg.key and arg.type == "select" and type(arg.values) == "table" then
                    local allowed = {}
                    for _, v in ipairs(arg.values) do allowed[v.value] = true end
                    rules[arg.key] = { allowed = allowed }
                end
            end
        end
    end
    self._rules = rules
    return rules
end

function Component:Changed(node, key, value)
    -- s6-interface-5x (round 13, step 11): a component not loaded only keeps the setting; its code reads it when it loads
    if not Components:Loaded(self.name) then
        TK.DB:MarkDirty()
        return
    end
    if self.OnSettingChanged then
        TK.SafeCall(self.OnSettingChanged, self, node, key, value)
    else
        TK.SafeCall(self.ApplySettings, self)
    end
    TK.DB:MarkDirty()
end

local function requireFile(dir, file)
    if not file then return end
    local module = (dir .. "/" .. file:gsub("%.lua$", "")):gsub("/", ".")
    local ok, err = xpcall(require, debug.traceback, module)
    if not ok then __tk:LogError("loading " .. module .. ": " .. tostring(err)) end
end

--- Called once by C# with the manifests. Loads every component's settings and the global ones' code, the profile,
--- then the code of the interface panels in use, and builds the UI.
function Components:Boot(manifests)
    -- s6-modular-g (interfaces, phase 2): the installed interfaces (they need the computer's settings for the active
    -- one), and their panels' code as components after the manifests' (core/interfaces.lua).
    TK.Machine:Load()
    TK.Interfaces:Load()
    local all = {}
    for i = 1, #manifests do all[i] = manifests[i] end
    for _, m in ipairs(TK.Interfaces:PanelManifests()) do all[#all + 1] = m end
    manifests = all
    for i = 1, #manifests do
        local m = manifests[i]
        local c = setmetatable({
            name = m.name,
            title = m.title or m.name,
            order = m.order or 100,
            version = m.version,
            dir = m.dir,
            defaults = {},
        }, Component)
        self.list[#self.list + 1] = c
        self.byName[c.name] = c
        self.files[c.name] = m.main or "main.lua"
        self.unloadable[c.name] = c.dir ~= nil and c.dir:sub(1, 11) == "interfaces/" or nil
        -- s6-interface-5x (round 12): the component whose files load, so what they register is known as its
        -- (TK.Bindings:RegisterCommand: an interface's panel's commands are inert while it is off)
        self.loading = c
        requireFile(m.dir, m.settings or "settings.lua")
        self.loading = nil
        -- s6-interface-5x (round 13, step 11): its commands and their default keys before the profile, loaded or not
        self:Declare(c, m.commands)
        -- what settings.lua made, put back when the component's code is dropped (Unload)
        local kept = {}
        for k, v in pairs(c) do kept[k] = v end
        self.settingsFields[c.name] = kept
        if not self.unloadable[c.name] then self:LoadMain(c) end
    end

    -- s6-modular-g (interfaces, phase 2): the active interface's profile, its defaults on its first use.
    TK.Startup:Load() -- the command line may select its defaults, in memory only
    TK.Machine:ApplyUIScale()
    TK.Machine:ApplyGraphics()
    TK.Interfaces:Loaded()
    -- s6-interface-5x (round 13, step 11): the interface panels the profile has in use, in the manifests' order
    for _, c in ipairs(self.list) do
        if self.unloadable[c.name] and TK.Interfaces:InUse(c.name) then self:LoadMain(c) end
    end

    for _, c in ipairs(self.list) do
        if self.loaded[c.name] then self:Enable(c) end
    end
    self:ReapplyAll()
    TK.Startup:Apply() -- existing setters, after the panels exist and before the login presentation
    TK.FireEvent("PLAYER_LOGIN")
    self.booted = true
    __tk:Log("interface panels loaded: " .. self:LoadedList())
    -- The client starts on the login screen (a UI reload in the world stays there); PLAYER_ENTERING_WORLD follows
    -- when Login enters the world.
    TK.Login:Start()
    TK.Startup:Notice()
end

--- Applies the whole profile again: every component's settings, positions, bindings and actions. s6-interface-5x (round
--- 13, step 11): first the interface panels the profile now has in use are loaded and the others unloaded (Sync).
function Components:ReapplyAll()
    self:Sync()
    self:Layer()
    TK.Machine:ApplyUIScale()
    for _, c in ipairs(self.list) do
        self.current = c
        if c.ApplySettings then TK.SafeCall(c.ApplySettings, c) end
    end
    self.current = nil
    TK.EditMode:RestoreAll()
    TK.FireEvent("TK_PROFILE_CHANGED")
end

-- ----- only what is turned on is loaded (s6-interface-5x, round 13, the separation's step 11; 5.18) -----

Components.files = {}          -- name -> its main file (the manifest's main)
Components.settingsFields = {} -- name -> { field = value }: what its settings.lua made
local bySource = {}            -- a chunk's source -> the component its folder is, or false

--- Whether a component's main.lua runs (TK.GetComponent is no test: a component not loaded has its settings).
function Components:Loaded(name) return self.loaded[name] == true end

--- The loaded interface panels' components, in order (the player's log at the start).
function Components:LoadedList()
    local out = {}
    for _, c in ipairs(self.list) do
        if self.loaded[c.name] and c.dir and c.dir:sub(1, 11) == "interfaces/" then out[#out + 1] = c.name end
    end
    return #out > 0 and table.concat(out, ", ") or "no interface panel"
end

-- The component whose folder holds a chunk ("@lua/interfaces/7x/panels/side/main.lua"; a tests' interface's from its own
-- folder, its full path), among the interface panels that load and unload.
local function componentOfSource(source)
    source = source:gsub("^@", ""):gsub("\\", "/")
    for name in pairs(Components.unloadable) do
        local dir = Components.byName[name].dir
        if source:sub(1, #dir + 5) == "lua/" .. dir .. "/" or source:find("/" .. dir:sub(12) .. "/", 1, true) then
            return name
        end
    end
    return false
end

-- The interface panel whose file runs at a stack level (debug.getinfo's, counted from this function's caller), or nil.
local function sourceOwner(level)
    local info = debug.getinfo(level + 1, "S")
    local source = info and info.source
    if not source then return nil end
    local name = bySource[source]
    if name == nil then
        name = componentOfSource(source)
        bySource[source] = name
    end
    return name or nil
end

--- Who owns what is made now (a listener, a registry's entry): the component loading, enabling or applying its settings
--- (with the panel PanelOn runs for), else the component whose file made it, depth levels up from the caller (2: the
--- caller's caller). Only an interface panel's (it may be unloaded): nil for the others.
function Components:Owner(depth)
    local c = self.loading or self.current
    if c then
        if self.unloadable[c.name] then return c.name, self.panel end
        return nil
    end
    local name = sourceOwner((depth or 2) + 1) -- not a tail call: it would take this level off the stack it counts
    return name
end

--- The owner of a frame CreateFrame makes now (Owner, of CreateFrame's caller), except one shared code makes on UIParent
--- (or with no parent): a singleton made on its first use while a panel's code runs (edit mode's movers, the dropdown's
--- list, a dialog's window) is no panel's. A panel's own roots are its file's, or its C:Own's.
function Components:FrameOwner(onRoot)
    local name, panel = self:Owner(3)
    if name and onRoot and sourceOwner(3) == nil then return nil end
    return name, panel
end

--- Records a frame as its owner's (Owner), to be destroyed with it.
function Components:Adopt(frame, name, panel)
    if not name or not self.unloadable[name] or rawget(frame, "__owner") then return end
    frame.__owner, frame.__panel = name, panel
    local list = self.owned[name] or {}
    list[#list + 1] = frame
    self.owned[name] = list
end

--- A component's commands as its manifest declares them, loaded or not (5.18, "Commands and their default keys are
--- declared as data"): { { name, text, keys = { key, ... }, newer = true } }. The profile's check keeps their bindings
--- (TK.DB.knownCommands), a first profile gets their keys (TK.DB.defaultBindings), an older one its newer commands'.
function Components:Declare(c, commands)
    for _, d in ipairs(commands or {}) do
        TK.Bindings:Declare(d.name, d.text, c.name)
        for _, key in ipairs(d.keys or {}) do TK.DB.defaultBindings[key] = d.name end
        if d.newer then table.insert(TK.DB.NEWER_COMMANDS, d.name) end
    end
end

--- Runs a component's main.lua (it registers its commands' functions, as at the start). s6-interface-5x (round 14; the
--- head's F4 note): an interface panel's TK fields its files set (Modern's TK.Bag, TK.CharacterWindow, TK.Look, TK.Social,
--- TK.Emotes) are noted, so Unload clears them and a reader finds nil, not the tables of a panel that is gone. (Only a
--- panel's own files add TK fields then: the shared code is loaded at the start, core/init.lua.)
function Components:LoadMain(c)
    local before = {}
    for k in pairs(TK) do before[k] = true end
    local was = self.loading
    self.loading = c
    requireFile(c.dir, self.files[c.name])
    self.loading = was
    self.loaded[c.name] = true
    if self.unloadable[c.name] then
        local made = {}
        for k in pairs(TK) do
            if not before[k] then made[#made + 1] = k end
        end
        self.made[c.name] = made
    end
end

--- The component's OnEnable, then PanelOn for each of its panels in use.
function Components:Enable(c)
    local was = self.current
    self.current = c
    if c.OnEnable then TK.SafeCall(c.OnEnable, c) end
    self.current = was
    self.started[c.name] = self.started[c.name] or {}
    for _, panel in ipairs(TK.Interfaces:PanelsOf(c.name)) do
        if TK.Interfaces:PanelInUse(panel) then self:PanelOn(c, panel.id) end
    end
end

--- A panel of a loaded component starts: its PanelOn, if it gives each panel its own lifecycle.
function Components:PanelOn(c, id)
    self.started[c.name][id] = true
    if not c.PanelOn then return end
    local was, wasPanel = self.current, self.panel
    self.current, self.panel = c, id
    TK.SafeCall(c.PanelOn, c, id)
    self.current, self.panel = was, wasPanel
end

--- Its settings applied, as ReapplyAll does.
local function apply(c)
    local was = Components.current
    Components.current = c
    if c.ApplySettings then TK.SafeCall(c.ApplySettings, c) end
    Components.current = was
end

--- A panel turned on in the game (__tk_start_panel, run by the host with the UI loading, LuaHost.StartPanel): its
--- component loaded and started if it is not (main.lua, OnEnable, PanelOn for its panels in use), else this panel's
--- PanelOn; then its settings, and PLAYER_LOGIN and, in the world, PLAYER_ENTERING_WORLD delivered to what it made
--- alone, as the client's start gives them; then a chat log's lines of the game screen so far (TK.Game.Chat.Replay:
--- drawing only). Wire: so a panel started late attaches the D20 requests it attaches at a start (TK.Game.Views.RequestPage
--- at PLAYER_LOGIN) and reads the game layer's state then (4a's one side-panel tab: TK.Game.SidePanel), and its first press
--- sends what it sends after a start with it on; changing this changes what the server sees.
function Components:Start(name, id)
    local c = self.byName[name]
    if not c or not self.unloadable[name] then return false end
    local panel
    if not self.loaded[name] then
        self:LoadMain(c)
        self:Enable(c)
    elseif id and not self.started[name][id] then
        self:PanelOn(c, id)
        panel = id
    else
        return true
    end
    apply(c)
    TK.DeliverTo(name, panel, "PLAYER_LOGIN")
    if TK.GameState:InWorld() then TK.DeliverTo(name, panel, "PLAYER_ENTERING_WORLD") end
    TK.Game.Chat.Replay(name, panel)
    return true
end

-- What an owner (panel: made for that panel) made, closed by its own hide path: each shown frame with an OnHide is hidden,
-- so its OnHide runs while its code is there (a destroyed frame fires none: W11). Wire: some of the game's state is
-- cleared only there (5.x's options page, interfaces/5x/panels/options/main.lua: H:DialogOptionPageShown(false), so a
-- server 0x21 then opens the save notice and not NewOptionPane's modal alert, OptionPane.cpp:1103); changing this
-- changes what the server sees.
local function close(name, panel)
    local list = Components.owned[name] or {}
    for i = #list, 1, -1 do
        local f = list[i]
        if not TK.IsDead(f) and (panel == nil or f.__panel == panel) and f.__scripts and f.__scripts.OnHide
            and f:IsShown() then
            f:Hide()
        end
    end
end

-- What an owner made, withdrawn from the registries and destroyed.
local function tearDown(name, panel)
    TK.Withdraw(name, panel)
    TK.WithdrawListeners(name, panel)
    local list, kept = Components.owned[name] or {}, {}
    for _, f in ipairs(list) do
        if panel == nil or f.__panel == panel then TK.DestroyFrame(f) elseif not TK.IsDead(f) then kept[#kept + 1] = f end
    end
    Components.owned[name] = kept
    -- the registries drop what they held of the frames destroyed with them (a child another owner registered)
    TK.Withdraw(nil, nil)
end

--- A panel of a loaded component turned off while a sibling stays: its PanelOff, then what its PanelOn made closed,
--- withdrawn and destroyed.
function Components:PanelOff(c, id)
    self.started[c.name][id] = nil
    if not c.PanelOff then return end
    local was, wasPanel = self.current, self.panel
    self.current, self.panel = c, id
    TK.SafeCall(c.PanelOff, c, id)
    self.current, self.panel = was, wasPanel
    close(c.name, id)
    tearDown(c.name, id)
end

--- An interface panel's component with no panel in use any more, unloaded (5.18, "Turning it off unloads it"): closed
--- first by its own path (its settings applied with its switches off, then PanelOff for each panel it started, then its
--- shown frames hidden), its listeners, registry entries and commands' functions withdrawn, its frames destroyed, and
--- its code dropped (package.loaded and the component's fields its main.lua made), so a later start loads it afresh.
--- Its settings stay in the profile and its commands declared, their keys inert.
function Components:Unload(c)
    apply(c)
    for id in pairs(self.started[c.name] or {}) do
        if c.PanelOff then
            local was, wasPanel = self.current, self.panel
            self.current, self.panel = c, id
            TK.SafeCall(c.PanelOff, c, id)
            self.current, self.panel = was, wasPanel
        end
    end
    close(c.name, nil)
    tearDown(c.name, nil)
    TK.Bindings:Withdraw(c.name)
    local prefix = c.dir:gsub("/", ".") .. "."
    local settings = prefix .. "settings"
    for module in pairs(package.loaded) do
        if module:sub(1, #prefix) == prefix and module ~= settings then package.loaded[module] = nil end
    end
    local kept = self.settingsFields[c.name] or {}
    for k in pairs(c) do
        if kept[k] == nil then c[k] = nil end
    end
    for k, v in pairs(kept) do c[k] = v end
    for _, k in ipairs(self.made[c.name] or {}) do TK[k] = nil end
    self.loaded[c.name], self.started[c.name], self.owned[c.name], self.made[c.name] = nil, nil, nil, nil
end

--- Loads the interface panels now in use and unloads those no longer in use (a panel's switch, a profile switched to or
--- reset: TK.Interfaces:SettingChanged, ReapplyAll); a component of several panels starts or stops just the panel. Nothing
--- is sent: it runs from our settings window or a profile switch, outside any game input (5.16's "Nothing is sent"),
--- and only which panels act on the next inputs changes.
function Components:Sync()
    if not self.booted then return end
    local changed = false
    for _, c in ipairs(self.list) do
        local name = c.name
        if self.unloadable[name] then
            local inUse = TK.Interfaces:InUse(name)
            if inUse and not self.loaded[name] then
                __tk:StartPanel(name, "")
                changed = true
            elseif not inUse and self.loaded[name] then
                self:Unload(c)
                changed = true
            elseif inUse then
                for _, panel in ipairs(TK.Interfaces:PanelsOf(name)) do
                    local on = TK.Interfaces:PanelInUse(panel)
                    if on and not self.started[name][panel.id] then
                        __tk:StartPanel(name, panel.id)
                        changed = true
                    elseif not on and self.started[name][panel.id] then
                        self:PanelOff(c, panel.id)
                        changed = true
                    end
                end
            end
        end
    end
    if changed then
        self:Layer()
        TK.FireEvent("UPDATE_BINDINGS")
        TK.EditMode:UpdateMovers()
    end
end

--- s6-interface-5x (round 14; the owner: a panel turned on applies at once, which includes being seen): a panel of
--- another interface turned on in the one in use draws over the latter's own. 7.x's and 5.x's screens and panels draw on
--- the LOW layer, so one of theirs mixed into the other was drawn under or between that screen's pieces; a mixed-in
--- panel's root frames on LOW go up to MEDIUM (Modern's panels' layer) while their interface is not the one in use, and
--- back down in their own (ReapplyAll after a switch, Sync after a panel is turned on). Drawing only.
function Components:Layer()
    local active = TK.Interfaces.active
    for name, list in pairs(self.owned) do
        local panel = TK.Interfaces:PanelsOf(name)[1]
        local mixed = panel ~= nil and panel.interface ~= active
        for _, f in ipairs(list) do
            if not TK.IsDead(f) and f:GetParent() == UIParent then
                local own = rawget(f, "__layer") or f:GetFrameStrata()
                f.__layer = own
                if own == "LOW" then f:SetFrameStrata(mixed and "MEDIUM" or "LOW") end
            end
        end
    end
end

--- The mod sandbox's native fallback (s6-sandbox notes, "The native fallback"): with replaced true, every root frame
--- of the component (C:Own) stays hidden, whatever its settings or its own code say (Region:Show keeps what they ask
--- for), and its edit-mode mover too; the component keeps running. With false its frames show as the settings and
--- its own code say now. For this session only: nothing is saved, and a UI reload replaces nothing. Returns false for
--- an unknown component, true otherwise; never raises.
function TK.ReplaceComponent(name, replaced)
    local c = type(name) == "string" and Components.byName[name] or nil
    if not c then return false end
    replaced = replaced == true
    if (c.replaced == true) == replaced then return true end
    TK.SafeCall(function()
        if replaced then
            for _, f in ipairs(c.roots or {}) do
                f.__want = __tk:IsShown(f.__h)
                __tk:SetShown(f.__h, false)
            end
            c.replaced = true
        else
            c.replaced = false
            for _, f in ipairs(c.roots or {}) do
                if TK.Visibility.frames[f] then TK.Visibility:Apply(f) else f:SetShown(f.__want) end
            end
        end
        TK.EditMode:UpdateMovers()
    end)
    return true
end

--- Every settings tree node of every component, in order.
function Components:AllNodes()
    local nodes = {}
    for _, c in ipairs(self.list) do
        for _, n in ipairs(c:SettingsNodes()) do
            n.component = c
            n.order = n.order or c.order
            nodes[#nodes + 1] = n
        end
    end
    table.sort(nodes, function(a, b)
        if a.order ~= b.order then return a.order < b.order end
        return (a.sub or 0) < (b.sub or 0)
    end)
    return nodes
end

-- ----- standard tabs for simple components -----

--- s6-ui-core (round 54; the owner's rule for every settings page): a setting an arg needs to have an effect (an arg's
--- requires = { TK.Needs(...), ... }, shown by core/settings.lua as a (!) after its title while it is on): label, as the
--- (!)'s tooltip names it ("Weather > Lightning"); met(db, node), whether it is as needed now (db: the page's
--- settings table, as disabled's). result (s6-ui-core round 60; the owner, 2026-10-06: "if its not that state it is
--- hidden, greyed out etc"): what an unmet need does to the arg: "grey" (the default: the (!) rule above), "hide" (not on
--- the page at all, shown again at once when it is met: a page's master switch) or "disable" (greyed and not usable).
--- For the odd need; one on a setting of the same page is TK.NeedSetting.
function TK.Needs(label, met, result) return { label = label, met = met, result = result } end

-- ----- s6-optimize (round 33): a setting as the game takes it -----
-- The owner (2026-10-06): "if feature Z is disabled but its subfeatures are enabled by default they should remain enabled
-- but greyed out (or hidden where specificly said) and NOT be applied". A row's needs (requires, with its groups') say
-- both: the page greys it (or hides or disables it: TK.Needs' result) while one is unmet, and the game reads it as off,
-- its own value kept. So code that applies a setting asks Applied (a row without a key: TK.NeedsMet) instead of testing
-- the setting's parent itself.

--- Whether every need of the row arg is met now (db: its page's settings table; node: its page). A grouped row as
--- TK.Settings.Controls gives it carries its groups' needs.
function TK.NeedsMet(arg, db, node)
    for _, need in ipairs(arg.requires or {}) do
        if not need.met(db, node) then return false end
    end
    return true
end

--- The rows of the component's pages by their keys, each as its page shows it (a grouped row with its groups' needs),
--- with its page; made once, as ValueRules.
function Component:Rows()
    if self._rows then return self._rows end
    local rows = {}
    local ok, nodes = pcall(self.SettingsNodes, self)
    for _, node in ipairs(ok and nodes or {}) do
        node.component = self
        for _, tab in ipairs(node.tabs or {}) do
            for _, arg in ipairs(TK.Settings.Controls(tab)) do
                if arg.key and not rows[arg.key] then rows[arg.key] = { arg = arg, node = node } end
            end
        end
    end
    self._rows = rows
    return rows
end

local function applied(c, key, db)
    local row = c:Rows()[key]
    if row and not TK.NeedsMet(row.arg, db, row.node) then return false end
    return db[key]
end

--- The setting key as the game takes it: its stored value while every need of its row is met, else false (a checked
--- sub-setting of a feature that is off does nothing). db: the page's settings table (the component's by default; a
--- bar's for the action bars). A component that reads its settings this way is applied again after any setting changes
--- (Components:ApplyReaders), as a need may be another page's (Global Illumination's, the World View's Shadows).
function Component:Applied(key, db)
    Components.readers[self] = true
    return applied(self, key, db or self:DB())
end

--- After a setting changes (the settings window's rows, S:SetOption), the loaded components that read theirs through
--- Applied are applied again, so a sub-setting follows a need on another page at once. Each ApplySettings is idempotent.
function Components:ApplyReaders()
    local list = {} -- taken first: an ApplySettings may make another component a reader
    for c in pairs(self.readers) do list[#list + 1] = c end
    for _, c in ipairs(list) do
        if self:Loaded(c.name) and c.ApplySettings then TK.SafeCall(c.ApplySettings, c) end
    end
end

--- s6-ui-core (round 60; the owner, 2026-10-06: "WE can define a option in a menu but internally says its a depancy of X
--- setting with state on ... I just want to make sure we are not HARD CODEING EVERY SETTING"): a need on the setting key
--- of the same page, in state (on when left out; false: off; any other value: equal to it). Its label is that setting's
--- own name on the page, read when the (!) shows ("Global Illumination", "Global Illumination off"); result as TK.Needs'.
--- s6-optimize (round 33): the setting as the game takes it (Applied, by the page's component), so a need on a
--- sub-setting that is not applied, its own need unmet, is unmet too (Lightning Silhouettes under a checked Global
--- Illumination with the Shadows option off); on a page without a component, as stored.
function TK.NeedSetting(key, state, result)
    local function value(db, node)
        local c = node and node.component
        if c then return applied(c, key, db) end
        return db[key]
    end
    local met
    if state == nil or state == true then
        met = function(db, node) return value(db, node) and true or false end
    elseif state == false then
        met = function(db, node) return not value(db, node) end
    else
        met = function(db, node) return value(db, node) == state end
    end
    return { key = key, state = state, met = met, result = result }
end

-- s6-ui-core (round 54): what the fading's sliders need to have an effect, their (!) (was disabled); round 60: by its key
local fading = TK.NeedSetting("fadeOut")

--- s6-ui-core (round 53; the owner, 2026-10-05: "the sliders on panels should have a box checked by default: Use global
--- transparency level [x]"): a panel's background transparency on one row, its slider and the box beside it: the
--- Interface page's UI Transparency while the box is ticked (the slider's (!)), the slider's own when not. Its keys'
--- defaults are TK.PanelTransparencyDefaults; its frames take it with TK.UI.HudPanel(frame, settings). (Alpha fades the
--- whole panel, its text and icons too.) s6-ui-core (round 56; s6-optimize's audit): each row draws the panels again when
--- it changes (its changed hook), and the slider starts at the UI's default (TK.UI.defaultTransparency).
TK.PanelTransparencyDefaults = { useGlobalTransparency = true, transparency = TK.UI.defaultTransparency }

local function redrawPanels() TK.UI.RedrawPanels() end

--- s6-ui-core (round 84; self-review r83-2): adds the rows to the end of a page's rows, args, fresh rows each call, as
--- interfaces/modern/slotmark.lua's M.Args, so no page takes them by a fixed count.
function TK.PanelTransparencyArgs(args)
    args[#args + 1] = { type = "break" }
    args[#args + 1] = { type = "range", key = "transparency", name = "Transparency (%)", min = 0, max = 100, step = 5,
        changed = redrawPanels,
        requires = { TK.Needs("Use Global Transparency off", function(db) return db.useGlobalTransparency == false end) } }
    args[#args + 1] = { type = "toggle", key = "useGlobalTransparency", name = "Use Global Transparency", changed = redrawPanels }
end

--- General Settings as for a Bartender bar without buttons: Enabled, Alpha and Fade Out, then extras. The Scale is
--- the Layout tab's (s6-modular-g, interfaces: TK.LayoutArgs). options.transparency: the panel has a background, with its
--- own transparency after the fading (TK.PanelTransparencyArgs).
function TK.StandardGeneralArgs(extra, options)
    options = options or {}
    local args = {
        { type = "toggle", key = "enabled", name = "Enabled" },
        { type = "header", name = options.header or "Style" },
        { type = "range", key = "alpha", name = "Alpha", min = 0.1, max = 1, step = 0.05 },
    }
    if not options.noFade then
        args[#args + 1] = { type = "toggle", key = "fadeOut", name = "Fade Out" }
        args[#args + 1] = { type = "break" }
        args[#args + 1] = { type = "range", key = "fadeOutAlpha", name = "Fade Out Alpha", min = 0, max = 1, step = 0.05, requires = { fading } }
        args[#args + 1] = { type = "range", key = "fadeOutDelay", name = "Fade Out Delay", min = 0, max = 1, step = 0.05, requires = { fading } }
    end
    if options.transparency then TK.PanelTransparencyArgs(args) end
    for _, a in ipairs(extra or {}) do args[#args + 1] = a end
    return args
end

TK.StandardVisibilityArgs = {
    { type = "description", name = "When the frame is shown. Hidden frames still appear in edit mode, so they can be moved." },
    { type = "toggle", key = "alwaysHide", name = "Always Hide" },
    -- s6-optimize (round 34): Visibility's driver ignores the modifier while Always Hide is on; keep its choice.
    { type = "group", requires = { TK.NeedSetting("alwaysHide", false) }, args = {
        { type = "select", key = "showModifier", name = "Show Only While Holding",
          values = { { value = "none", text = "Always shown" }, { value = "SHIFT", text = "Shift" },
                     { value = "CTRL", text = "Ctrl" }, { value = "ALT", text = "Alt" } } },
    } },
}

--- Gives a component the three standard tabs. parent puts its page under another entry of the settings list (an id, or
--- a title's text such as "Bars": core/settings.lua's header); layoutExtra adds controls at the end of its Layout tab.
function Component:StandardSettings(positionKey, generalExtra, options)
    options = options or {}
    if options.transparency then
        self.defaults = self.defaults or {}
        for k, v in pairs(TK.PanelTransparencyDefaults) do
            if self.defaults[k] == nil then self.defaults[k] = v end
        end
    end
    self.tabs = {
        { name = "General Settings", args = TK.StandardGeneralArgs(generalExtra, options) },
        { name = "Visibility", args = TK.StandardVisibilityArgs },
        -- s6-modular-g (interfaces, phase 1): the Layout tab (scale and place) took the Alignment tab's place.
        { name = "Layout", args = TK.LayoutArgs(function() return positionKey end, { extra = options.layoutExtra }) },
    }
    self.parent = options.parent -- s6-ui-settings (nested settings menus): was group, one level of titles
    self.sub = options.sub
end

local baseNodes = Component.SettingsNodes
function Component:SettingsNodes()
    local nodes = baseNodes(self)
    nodes[1].parent = self.parent
    nodes[1].sub = self.sub
    return nodes
end
